/* Google Fonts Import */
@import url('https://fonts.googleapis.com/css2?family=Albert+Sans:wght@400;500;600&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700;800&display=swap');

/* Custom Font Declaration */
@font-face {
  font-family: 'Mona Sans SemiBold Wide';
  src: url('@assets/Mona-Sans-SemiBoldWide_1754657900749.otf') format('opentype');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}

/* Fonts loaded via HTML head for better performance */

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 220 27% 3%;
    --foreground: 0 0% 98%;
    --card: 220 25% 8%;
    --card-foreground: 0 0% 98%;
    --popover: 220 25% 8%;
    --popover-foreground: 0 0% 95%;
    --primary: 185 84% 55%;
    --primary-foreground: 220 27% 8%;
    --secondary: 220 20% 12%;
    --secondary-foreground: 0 0% 90%;
    --muted: 220 20% 12%;
    --muted-foreground: 0 0% 75%;
    --accent: 185 84% 55%;
    --accent-foreground: 220 27% 8%;
    --destructive: 0 62% 50%;
    --destructive-foreground: 0 0% 98%;
    --border: 220 20% 18%;
    --input: 220 20% 12%;
    --ring: 185 84% 55%;
    --radius: 0rem;
  }

  * {
    @apply border-border;
  }

  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  #root {
    background: linear-gradient(135deg, hsl(220, 27%, 3%) 0%, hsl(220, 25%, 5%) 100%);
    color: #fafafa !important;
    min-height: 100vh;
    position: relative;
  }

  #root::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background:
      radial-gradient(circle at 30% 30%, hsl(185, 84%, 55%) 0%, transparent 40%),
      radial-gradient(circle at 70% 70%, hsl(285, 85%, 60%) 0%, transparent 40%);
    opacity: 0.6;
    pointer-events: none;
    z-index: -1;
    will-change: transform;
  }

  body {
    @apply bg-background text-foreground overflow-x-hidden;
    font-family: 'Albert Sans', system-ui, sans-serif !important;
    line-height: 1.6;
    background: transparent !important;
    color: #ffffff !important;
    font-weight: 400;
    cursor: auto !important;
  }

  * {
    cursor: auto !important;
  }

  /* Performance optimizations */
  *,
  *::before,
  *::after {
    will-change: auto;
  }

  /* GPU acceleration for smooth animations */
  .gpu-accelerated {
    transform: translateZ(0);
    backface-visibility: hidden;
    perspective: 1000px;
  }

  /* Optimized transforms for common animations */
  .transform-gpu {
    transform: translate3d(0, 0, 0);
  }

  /* Performance-optimized motion */
  .motion-safe {
    backface-visibility: hidden;
    perspective: 1000px;
  }

  /* Optimized scrolling */
  html {
    scroll-behavior: smooth;
  }

  @supports (scroll-behavior: smooth) {
    html {
      scroll-behavior: smooth;
    }
  }

  /* Reduced motion support */
  @media (prefers-reduced-motion: reduce) {

    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }

    .motion-reduce {
      transform: none !important;
      animation: none !important;
    }
  }

  /* Optimize fonts */
  @font-face {
    font-family: 'Jost';
    font-display: swap;
    font-weight: 300 800;
  }

  /* Image optimization */
  img {
    content-visibility: auto;
    contain: layout style paint;
  }

  /* Canvas optimization */
  canvas {
    will-change: transform;
    image-rendering: optimizeSpeed;
  }

  /* Intersection observer performance */
  .lazy-load {
    content-visibility: auto;
    contain-intrinsic-size: 1px 500px;
  }

  html {
    scroll-behavior: smooth;
    background: transparent !important;
  }

  /* Glassmorphism utilities */
  .glass-card {
    background: rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    box-shadow:
      0 8px 32px rgba(0, 0, 0, 0.3),
      inset 0 1px 0 rgba(255, 255, 255, 0.1);
  }

  .glass-intense {
    background: rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(30px);
    -webkit-backdrop-filter: blur(30px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    box-shadow:
      0 12px 40px rgba(0, 0, 0, 0.4),
      inset 0 1px 0 rgba(255, 255, 255, 0.15);
  }

  .grain-texture {
    position: relative;
  }

  /* Responsive CTA Button Style */
  .cta-button {
    background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 50%, #1e3a8a 100%) !important;
    border: 1px solid rgba(59, 130, 246, 0.3);
    box-shadow:
      0 4px 20px rgba(30, 58, 138, 0.4),
      inset 0 1px 0 rgba(255, 255, 255, 0.1);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    border-radius: 0 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    -webkit-tap-highlight-color: transparent;
    touch-action: manipulation;
    min-height: 48px !important;
    padding: 12px 24px !important;
  }

  .cta-button span {
    font-size: 14px !important;
    font-weight: 600 !important;
    line-height: 1.2 !important;
    white-space: nowrap !important;
  }

  /* Navbar specific button sizing */
  nav .cta-button {
    min-height: 40px !important;
    padding: 8px 16px !important;
    font-size: 14px !important;
  }

  nav .cta-button span {
    font-size: 14px !important;
    font-weight: 600 !important;
  }

  @media (min-width: 640px) {
    .cta-button {
      padding: 16px 32px !important;
      min-height: 56px !important;
    }

    .cta-button span {
      font-size: 16px !important;
      font-weight: 700 !important;
    }

    /* Keep navbar buttons smaller on desktop too */
    nav .cta-button {
      min-height: 44px !important;
      padding: 10px 20px !important;
    }

    nav .cta-button span {
      font-size: 15px !important;
      font-weight: 600 !important;
    }
  }

  .cta-button:hover {
    background: linear-gradient(135deg, #1d4ed8 0%, #2563eb 50%, #1d4ed8 100%) !important;
    box-shadow:
      0 6px 30px rgba(29, 78, 216, 0.5),
      inset 0 1px 0 rgba(255, 255, 255, 0.15);
    transform: translateY(-1px);
  }

  .cta-button:active {
    transform: translateY(0px) scale(0.98) !important;
  }

  /* Typography Classes */
  .modern-heritage {
    font-family: 'Modern Heritage Display', serif !important;
    font-weight: normal !important;
    letter-spacing: 0.02em;
  }

  .jost-secondary {
    font-family: 'Albert Sans', system-ui, sans-serif !important;
    font-weight: 400;
  }

  .open-sans {
