@layer components {
  .neo-card {
    @apply bg-card border border-border rounded-2xl p-8;
    box-shadow:
      0 0 0 1px rgba(255, 255, 255, 0.05),
      0 8px 32px rgba(0, 0, 0, 0.4);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .neo-card:hover {
    transform: translateY(-4px);
    box-shadow:
      0 0 0 1px rgba(255, 255, 255, 0.1),
      0 16px 64px rgba(0, 0, 0, 0.6),
      0 0 80px rgba(138, 43, 226, 0.1);
  }

  .glow-text {
    background: linear-gradient(135deg, #6966ff 0%, #cb5cff 50%, #d642ff 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    color: #22d3ee !important;
    /* Fallback for unsupported browsers */
  }

  /* Fix all gradient text backgrounds */
  .bg-clip-text {
    background-color: transparent !important;
  }

  .text-gradient {
    background: linear-gradient(135deg, #22d3ee 0%, #06b6d4 50%, #0891b2 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    color: #22d3ee !important;
    /* Fallback for unsupported browsers */
  }

  /* Simple Project Card Border */
  .project-card-border {
    border: 0.6px solid rgba(255, 255, 255, 0.3);
    transition: all 0.3s ease;
  }

  .stroke-text {
    -webkit-text-stroke: 2px rgba(255, 255, 255, 0.3);
    text-stroke: 2px rgba(255, 255, 255, 0.3);
  }

  .cyber-grid {
    --mouse-x: 50%;
    --mouse-y: 50%;
    --wave-intensity: 0.2;
    position: relative;
    overflow: hidden;
    background:
      radial-gradient(circle at 50% 40%, rgba(79, 172, 254, 0.04) 0%, transparent 50%),
      linear-gradient(135deg,
        rgba(4, 4, 6, 1) 0%,
        rgba(6, 6, 10, 0.98) 50%,
        rgba(4, 4, 6, 1) 100%);
    will-change: transform;
  }

  .cyber-grid::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background:
      radial-gradient(circle 150px at var(--mouse-x, 50%) var(--mouse-y, 50%),
        rgba(79, 172, 254, 0.08) 0%,
        rgba(79, 172, 254, 0.03) 40%,
        transparent 70%);
    opacity: var(--wave-intensity, 0.5);
    transition: opacity 0.9s ease;
    pointer-events: none;
    z-index: 2;
  }

  /* Simplified grid intersection points */
  .cyber-grid .grid-intersection {
    position: absolute;
    width: 2px;
    height: 2px;
    background: rgba(79, 172, 254, 0.6);
    border-radius: 50%;
    opacity: 0.4;
  }

  .cyber-grid canvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 3;
    opacity: 0.9;
  }

  /* Hero Text - Normal Static */
  .hero-text-hover {
    position: relative;
    transition: all 0.3s ease;
  }

  .hero-text-hover:hover {
    transform: scale(1.02);
  }



  .floating-orb {
    position: absolute;
    border-radius: 50%;
    background: radial-gradient(circle at 30% 30%, rgba(138, 43, 226, 0.8), rgba(255, 107, 107, 0.6));
    filter: blur(40px);
    animation: float 6s ease-in-out infinite;
  }

  .magnetic-hover {
    transition: transform 0.2s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }

  .text-glitch {
    position: relative;
    font-weight: 700;
  }

  .text-glitch::before,
  .text-glitch::after {
    content: attr(data-text);
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
  }

  .text-glitch::before {
    animation: glitch-1 2s infinite;
    color: #FF6B6B;
    z-index: -1;
  }

  .text-glitch::after {
    animation: glitch-2 2s infinite;
    color: #4ECDC4;
    z-index: -2;
  }

  .morphing-border {
    position: relative;
    border-radius: 1rem;
    background: linear-gradient(45deg, transparent, rgba(138, 43, 226, 0.1), transparent);
    padding: 2px;
  }

  .morphing-border::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: linear-gradient(45deg, #8A2BE2, #FF6B6B, #4ECDC4, #8A2BE2);
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask-composite: exclude;
    animation: border-rotate 3s linear infinite;
  }

  .section-divider {
    width: 100%;
    height: 200px;
    background: linear-gradient(90deg,
        transparent,
        rgba(138, 43, 226, 0.1) 20%,
        rgba(255, 107, 107, 0.1) 40%,
        rgba(78, 205, 196, 0.1) 60%,
        rgba(138, 43, 226, 0.1) 80%,
        transparent);
    mask: radial-gradient(ellipse at center, black 30%, transparent 70%);
  }
}

@keyframes grid-move {
  0% {
    transform: translate(0, 0);
  }

  100% {
    transform: translate(50px, 50px);
  }
}

@keyframes liquid-wave {

  0%,
  100% {
    transform: scale(1) rotate(0deg);
    opacity: 0.7;
  }

  25% {
    transform: scale(1.1) rotate(90deg);
    opacity: 0.5;
  }

  50% {
    transform: scale(0.9) rotate(180deg);
    opacity: 0.8;
  }

  75% {
    transform: scale(1.05) rotate(270deg);
    opacity: 0.6;
  }
}

@keyframes liquid-float {

  0%,
  100% {
    transform: translateY(0px) scale(1);
    opacity: 0.4;
  }

  33% {
    transform: translateY(-20px) scale(1.1);
    opacity: 0.6;
  }

  66% {
    transform: translateY(10px) scale(0.95);
    opacity: 0.3;
  }
}

@keyframes float {

  0%,
  100% {
    transform: translateY(0px) rotate(0deg);
  }

  33% {
    transform: translateY(-20px) rotate(120deg);
  }

  66% {
    transform: translateY(10px) rotate(240deg);
  }
}

@keyframes glitch-1 {

  0%,
  100% {
    transform: translate(0);
  }

  20% {
    transform: translate(-2px, 2px);
  }

  40% {
    transform: translate(-2px, -2px);
  }

  60% {
    transform: translate(2px, 2px);
  }

  80% {
    transform: translate(2px, -2px);
  }
}

@keyframes glitch-2 {

  0%,
  100% {
    transform: translate(0);
  }

  20% {
    transform: translate(2px, -2px);
  }

  40% {
    transform: translate(2px, 2px);
  }

  60% {
    transform: translate(-2px, -2px);
  }

  80% {
    transform: translate(-2px, 2px);
  }
}

@keyframes border-rotate {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

.line-clamp-3 {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

@keyframes pulse-glow {

  0%,
  100% {
    box-shadow: 0 0 20px rgba(138, 43, 226, 0.2);
  }

  50% {
    box-shadow: 0 0 40px rgba(138, 43, 226, 0.4);
  }
}

